CREATE TABLE governed_authority (authority_id TEXT NOT NULL, authority_version INTEGER NOT NULL CHECK(authority_version>0), origin_locator TEXT NOT NULL, content_hash TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(authority_id,authority_version));
CREATE TABLE authority_scope (authority_id TEXT NOT NULL, authority_version INTEGER NOT NULL, context_revision_id TEXT NOT NULL, parameter_reference TEXT NOT NULL, PRIMARY KEY(authority_id,authority_version,context_revision_id,parameter_reference), FOREIGN KEY(authority_id,authority_version) REFERENCES governed_authority(authority_id,authority_version));
CREATE TABLE authority_state (authority_id TEXT NOT NULL, authority_version INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN('PUBLISHED','ACTIVE','REVOKED','SUPERSEDED')), state_changed_at TEXT NOT NULL, last_event_id TEXT, PRIMARY KEY(authority_id,authority_version), FOREIGN KEY(authority_id,authority_version) REFERENCES governed_authority(authority_id,authority_version));
CREATE TABLE authority_temporal_boundary (authority_id TEXT NOT NULL, authority_version INTEGER NOT NULL, effective_from TEXT NOT NULL, effective_until TEXT, PRIMARY KEY(authority_id,authority_version), CHECK(effective_until IS NULL OR effective_until>effective_from), FOREIGN KEY(authority_id,authority_version) REFERENCES governed_authority(authority_id,authority_version));
CREATE TABLE authority_event (event_id TEXT PRIMARY KEY, authority_id TEXT NOT NULL, authority_version INTEGER NOT NULL, event_type TEXT NOT NULL CHECK(event_type IN('PUBLISHED','REVOKED','SUPERSEDED')), actor_reference TEXT NOT NULL, reason TEXT NOT NULL, successor_authority_id TEXT, successor_authority_version INTEGER, registered_at TEXT NOT NULL, FOREIGN KEY(authority_id,authority_version) REFERENCES governed_authority(authority_id,authority_version));
CREATE INDEX authority_scope_lookup ON authority_scope(context_revision_id,parameter_reference);
CREATE INDEX authority_temporal_lookup ON authority_temporal_boundary(effective_from,effective_until);
CREATE TRIGGER authority_immutable_update BEFORE UPDATE ON governed_authority BEGIN SELECT RAISE(ABORT,'immutable'); END;
CREATE TRIGGER authority_immutable_delete BEFORE DELETE ON governed_authority BEGIN SELECT RAISE(ABORT,'no delete'); END;
CREATE TRIGGER authority_scope_immutable_update BEFORE UPDATE ON authority_scope BEGIN SELECT RAISE(ABORT,'immutable'); END;
CREATE TRIGGER authority_scope_immutable_delete BEFORE DELETE ON authority_scope BEGIN SELECT RAISE(ABORT,'no delete'); END;
CREATE TRIGGER authority_boundary_immutable_update BEFORE UPDATE ON authority_temporal_boundary BEGIN SELECT RAISE(ABORT,'immutable'); END;
CREATE TRIGGER authority_boundary_immutable_delete BEFORE DELETE ON authority_temporal_boundary BEGIN SELECT RAISE(ABORT,'no delete'); END;
CREATE TRIGGER authority_event_append_only BEFORE UPDATE ON authority_event BEGIN SELECT RAISE(ABORT,'append only'); END;
CREATE TRIGGER authority_event_no_delete BEFORE DELETE ON authority_event BEGIN SELECT RAISE(ABORT,'no delete'); END;
CREATE TRIGGER authority_state_transition BEFORE UPDATE OF status ON authority_state WHEN NOT((OLD.status='PUBLISHED' AND NEW.status='ACTIVE') OR (OLD.status='ACTIVE' AND NEW.status IN('REVOKED','SUPERSEDED'))) BEGIN SELECT RAISE(ABORT,'invalid transition'); END;
CREATE TRIGGER authority_state_no_delete BEFORE DELETE ON authority_state BEGIN SELECT RAISE(ABORT,'no delete'); END;
CREATE TRIGGER authority_temporal_no_overlap BEFORE INSERT ON authority_temporal_boundary WHEN EXISTS(SELECT 1 FROM authority_temporal_boundary b WHERE b.authority_id=NEW.authority_id AND b.authority_version=NEW.authority_version AND COALESCE(b.effective_until,'9999-12-31T23:59:59Z')>NEW.effective_from AND COALESCE(NEW.effective_until,'9999-12-31T23:59:59Z')>b.effective_from) BEGIN SELECT RAISE(ABORT,'overlap'); END;
